import{_ as a,o,c as t,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Macro-Notes.md","filePath":"manual-en/Macro-Notes.md","lastUpdated":1785684581000}'),r={name:"manual-en/Macro-Notes.md"};function s(d,e,c,i,m,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h4 id="_14-2-12-additional-notes" tabindex="-1">14.2.12 Additional Notes <a class="header-anchor" href="#_14-2-12-additional-notes" aria-label="Permalink to &quot;14.2.12 Additional Notes&quot;">​</a></h4><h4 id="_14-2-12-1-calling-macros-from-macros" tabindex="-1">14.2.12.1 Calling Macros from Macros <a class="header-anchor" href="#_14-2-12-1-calling-macros-from-macros" aria-label="Permalink to &quot;14.2.12.1 Calling Macros from Macros&quot;">​</a></h4><p>If the body of macro A includes a call to macro B, the call can use macro arguments (including <code>!*</code>) and macro variables as part of arguments to B. For <code>!TOKENS</code> arguments, the argument or variable name counts as one token regardless of the number that it expands into; for <code>!CHAREND</code> and <code>!ENCLOSE</code> arguments, the delimiters come only from the call, not the expansions; and <code>!CMDEND</code> ends at the calling command, not any end of command within an argument or variable.</p><p>Macro functions are not supported as part of the arguments in a macro call. To get the same effect, use <code>!LET</code> to define a macro variable, then pass the macro variable to the macro.</p><p>When macro A calls macro B, the order of their <code>DEFINE</code> commands doesn’t matter, as long as macro B has been defined when A is called.</p><h4 id="_14-2-12-2-command-terminators" tabindex="-1">14.2.12.2 Command Terminators <a class="header-anchor" href="#_14-2-12-2-command-terminators" aria-label="Permalink to &quot;14.2.12.2 Command Terminators&quot;">​</a></h4><p>Macros and command terminators require care. Macros honor the syntax differences between interactive and batch syntax (see <a href="./Syntax-Variants">Syntax Variants</a>), which means that the interpretation of a macro can vary depending on the syntax mode in use. We assume here that interactive mode is in use, in which ‘.’ at the end of a line is the primary way to end a command.</p><p>The <code>DEFINE</code> command needs to end with ‘.’ following the <code>!ENDDEFINE</code>. The macro body may contain ‘.’ if it is intended to expand to whole commands, but using ‘.’ within a macro body that expands to just syntax fragments (such as a list of variables) will cause syntax errors.</p><p>Macro directives such as <code>!IF</code> and <code>!DO</code> do not end with ‘.’.</p><h4 id="_14-2-12-3-expansion-contexts" tabindex="-1">14.2.12.3 Expansion Contexts <a class="header-anchor" href="#_14-2-12-3-expansion-contexts" aria-label="Permalink to &quot;14.2.12.3 Expansion Contexts&quot;">​</a></h4><p>Macros do not expand within comments, whether introduced within a line by <code>/*</code> or as a separate COMMENT or ‘<em>’ commands (see <a href="./COMMENT">COMMENT</a>). (SPSS does expand macros in COMMENT and ‘</em>’.)</p><p>Macros do not expand within quoted strings.</p><p>Macros are expanded in the <code>TITLE</code> and <code>SUBTITLE</code> commands as long as their arguments are not quoted strings.</p><h4 id="_14-2-12-4-preserve-and-restore" tabindex="-1">14.2.12.4 PRESERVE and RESTORE <a class="header-anchor" href="#_14-2-12-4-preserve-and-restore" aria-label="Permalink to &quot;14.2.12.4 PRESERVE and RESTORE&quot;">​</a></h4><p>Some macro bodies might use the SET command to change certain settings. When this is the case, consider using the PRESERVE and RESTORE commands to save and then restore these settings. See <a href="./PRESERVE-and-RESTORE">PRESERVE and RESTORE</a>.</p>',15)])])}const u=a(r,[["render",s]]);export{p as __pageData,u as default};
